
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_dk_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_dk", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([9.420557050339153e+01, 9.055898931822104e+01, 8.557358645350376e+01, 7.890730806741198e+01, 7.027181632352942e+01, 5.957977510425392e+01, 4.715999203333653e+01, 3.395020181941715e+01, 2.139870972755460e+01, 1.089597209896757e+01, 4.679759677979524e+00, 2.518815061093659e+00, 1.909045662753392e+00, 1.272826125006621e+00, 6.370412278376850e-01, 2.293734857731648e-01, 2.345149397007311e-01, 5.199038209043514e-01, 5.950528714616256e-01, 5.728675043657047e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


